package com.xfusion.fusiondesk.evaluation;
import com.fasterxml.jackson.databind.*;import com.xfusion.fusiondesk.exception.BusinessException;import java.nio.file.*;import java.util.*;
public class EvaluationReportWriter {
    private final ObjectMapper json=new ObjectMapper().enable(SerializationFeature.INDENT_OUTPUT);private final Path directory;
    public EvaluationReportWriter(Path directory){this.directory=directory;}
    public Path write(EvaluationReport report){try{Files.createDirectories(directory);String name=report.promptVersion().equals("baseline-v0")?"baseline-v0.json":"optimized-"+report.promptVersion()+".json";Path path=directory.resolve(name);json.writeValue(path.toFile(),report);generateComparisonIfReady();return path;}catch(Exception e){throw new BusinessException("Failed to write evaluation report.",e);}}
    public void generateComparisonIfReady(){Path baseline=directory.resolve("baseline-v0.json"),optimized=directory.resolve("optimized-v1.json");if(!Files.exists(baseline)||!Files.exists(optimized))return;try{EvaluationReport b=json.readValue(baseline.toFile(),EvaluationReport.class),o=json.readValue(optimized.toFile(),EvaluationReport.class);Files.writeString(directory.resolve("comparison.md"),comparison(b,o));}catch(Exception e){throw new BusinessException("Failed to generate evaluation comparison.",e);}}
    private String comparison(EvaluationReport b,EvaluationReport o){StringBuilder md=new StringBuilder("# FusionDesk AI Evaluation Comparison\n\n");md.append("Same dataset: `").append(b.datasetResource()).append("`; same model: `").append(b.model()).append("`. Injection resistance is adversarial exact match.\n\n");md.append("| Metric | Baseline | Optimized | Delta |\n|---|---:|---:|---:|\n");row(md,"Schema Valid Rate",b.metrics().schemaValidRate(),o.metrics().schemaValidRate());row(md,"Category Accuracy",b.metrics().categoryAccuracy(),o.metrics().categoryAccuracy());row(md,"Priority Accuracy",b.metrics().priorityAccuracy(),o.metrics().priorityAccuracy());row(md,"Exact Match",b.metrics().exactMatchRate(),o.metrics().exactMatchRate());row(md,"Injection Resistance",b.metrics().injectionResistanceRate(),o.metrics().injectionResistanceRate());failures(md,"Baseline Failures",b);failures(md,"Optimized Failures",o);return md.toString();}
    private void row(StringBuilder md,String name,double b,double o){md.append(String.format(Locale.ROOT,"| %s | %.2f%% | %.2f%% | %+.2f pp |%n",name,b,o,o-b));}
    private void failures(StringBuilder md,String title,EvaluationReport report){md.append("\n## ").append(title).append("\n\n");boolean any=false;for(EvaluationResult r:report.results())if(!r.categoryCorrect()||!r.priorityCorrect()){any=true;md.append("- `").append(r.caseId()).append("`: expected ").append(r.expectedCategory()).append('/').append(r.expectedPriority()).append(", predicted ").append(r.schemaValid()?r.predictedCategory()+"/"+r.predictedPriority():"INVALID").append(" — ").append(failureReason(r)).append('\n');}if(!any)md.append("None\n");}
    private String failureReason(EvaluationResult r){if(!r.schemaValid())return r.error();if(!r.categoryCorrect()&&!r.priorityCorrect())return "category and priority mismatch";return r.categoryCorrect()?"priority mismatch":"category mismatch";}
}
